"""otb_benchmark.ipynb: generated by conf_pipeline.make_notebook, runs end to end in tiny mode."""

from __future__ import annotations

import os
import subprocess
import sys
from pathlib import Path

import nbformat
import pandas as pd
import pytest
from nbclient import NotebookClient

REPO = Path(__file__).resolve().parent.parent


@pytest.mark.slow
def test_notebook_generates_and_executes_in_tiny_mode(tmp_path, monkeypatch):
    subprocess.run([sys.executable, "-m", "conf_pipeline.make_notebook"], cwd=REPO, check=True)
    nb = nbformat.read(REPO / "otb_benchmark.ipynb", as_version=4)
    assert nb.cells[0].cell_type == "markdown"
    assert any("OTB_PRESET" in c.source for c in nb.cells)

    # The kernel inherits the test process environment.
    monkeypatch.setenv("OTB_PRESET", "tiny")
    monkeypatch.setenv("OTB_OUT_DIR", str(tmp_path))
    monkeypatch.setenv("PYTHONHASHSEED", "0")
    client = NotebookClient(nb, timeout=900, kernel_name="python3",
                            resources={"metadata": {"path": str(REPO)}})
    client.execute()

    assert (tmp_path / "runs.jsonl").exists()
    assert (tmp_path / "oracle_static.json").exists()
    assert (tmp_path / "report" / "report.md").exists()
    assert (tmp_path / "report" / "analysis.md").exists()
    # tiny freezes at window 1, so its 3-window stream has a tail to rank on.
    summary = pd.read_csv(tmp_path / "report" / "summary.csv")
    assert summary["lag_ari_win_tail_mean"].notna().any()


def test_notebook_regret_display_reads_the_tail_region():
    from conf_pipeline import make_notebook

    assert 'regret[regret["region"] == "tail"]' in make_notebook.REPORT


def test_the_notebook_on_disk_is_the_generated_one():
    from conf_pipeline import make_notebook

    on_disk = nbformat.read(REPO / "otb_benchmark.ipynb", as_version=4)
    assert [(c.cell_type, c.source) for c in on_disk.cells] == [
        (c.cell_type, c.source) for c in make_notebook.build().cells
    ]
